import unreal

def inspect_obj(path):
    obj = unreal.EditorAssetLibrary.load_asset(path)
    print("OBJ", path, obj, obj.get_class().get_name() if obj else "None")
    if not obj: return
    attrs = [n for n in dir(obj) if any(k in n.lower() for k in ["source","target","rig","root","chain","pose","mesh","skeleton","retarget"])]
    print("ATTRS", attrs)
    for n in attrs:
        try:
            v = getattr(obj,n)
            if not callable(v): print("ATTR", n, "=", v)
        except Exception as e: print("ATTR_ERR", n, repr(e))
    for prop in ["source_ik_rig_asset","target_ik_rig_asset","source_preview_mesh","target_preview_mesh","retarget_pose","retarget_root","source_ik_rig","target_ik_rig","asset_import_data"]:
        try: print("PROP", prop, "=", obj.get_editor_property(prop))
        except Exception as e: pass

inspect_obj("/Game/Characters/Heroes/Mannequin/Rig/RTG_Mannequin")
